#!/usr/bin/env pwsh
$basedir=Split-Path $MyInvocation.MyCommand.Definition -Parent

$exe=""
$pathsep=":"
$env_node_path=$env:NODE_PATH
$new_node_path="C:\WorkSpace\location_tracker\backend\node_modules\.pnpm\ts-jest@29.4.15_@babel+core_93a990b103b91b70acd88cc4507d4ca7\node_modules\ts-jest\node_modules;C:\WorkSpace\location_tracker\backend\node_modules\.pnpm\ts-jest@29.4.15_@babel+core_93a990b103b91b70acd88cc4507d4ca7\node_modules;C:\WorkSpace\location_tracker\backend\node_modules\.pnpm\node_modules"
if ($PSVersionTable.PSVersion -lt "6.0" -or $IsWindows) {
  # Fix case when both the Windows and Linux builds of Node
  # are installed in the same directory
  $exe=".exe"
  $pathsep=";"
} else {
  $new_node_path="/proc/cygdrive/c/WorkSpace/location_tracker/backend/node_modules/.pnpm/ts-jest@29.4.15_@babel+core_93a990b103b91b70acd88cc4507d4ca7/node_modules/ts-jest/node_modules:/proc/cygdrive/c/WorkSpace/location_tracker/backend/node_modules/.pnpm/ts-jest@29.4.15_@babel+core_93a990b103b91b70acd88cc4507d4ca7/node_modules:/proc/cygdrive/c/WorkSpace/location_tracker/backend/node_modules/.pnpm/node_modules"
}
if ([string]::IsNullOrEmpty($env_node_path)) {
  $env:NODE_PATH=$new_node_path
} else {
  $env:NODE_PATH="$new_node_path$pathsep$env_node_path"
}

$ret=0
if (Test-Path "$basedir/node$exe") {
  # Support pipeline input
  if ($MyInvocation.ExpectingInput) {
    $input | & "$basedir/node$exe"  "$basedir/../ts-jest/cli.js" $args
  } else {
    & "$basedir/node$exe"  "$basedir/../ts-jest/cli.js" $args
  }
  $ret=$LASTEXITCODE
} else {
  # Support pipeline input
  if ($MyInvocation.ExpectingInput) {
    $input | & "node$exe"  "$basedir/../ts-jest/cli.js" $args
  } else {
    & "node$exe"  "$basedir/../ts-jest/cli.js" $args
  }
  $ret=$LASTEXITCODE
}
$env:NODE_PATH=$env_node_path
exit $ret
